#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll solve(ll a, ll b, ll k) {
    if (b < a) return (1LL << 60);
    if (a == b) return 0;

    ll n = b - a;
    vector<ll> largestDivisor(static_cast<size_t>(n + 1), 0);

    for (ll i = 2; i <= k; ++i) {
        ll remainder = a % i;
        ll offset = remainder == 0 ? 0 : i - remainder;

        for (ll index = offset; index <= n;) {
            largestDivisor[static_cast<size_t>(index)] = i;
            if (n - index < i) break;
            index += i;
        }
    }

    using State = pair<ll, ll>;
    priority_queue<State, vector<State>, greater<State>> active;

    auto addState = [&](ll value, ll cost, ll divisor) {
        ll reach = max(1LL, divisor - 1);
        ll expiration = value + min(reach, b - value);
        active.emplace(cost, expiration);
    };

    addState(a, 0, largestDivisor[0]);

    ll answer = 0;
    for (ll value = a + 1; value <= b; ++value) {
        while (!active.empty() && active.top().second < value)
            active.pop();

        answer = active.top().first + 1;
        addState(value, answer,
                 largestDivisor[static_cast<size_t>(value - a)]);
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, k;
    cin >> b >> a >> k;

    ll answer = 0;
    ll remainder = b % k;

    if (b - remainder >= a) {
        b -= remainder;
        if (remainder != 0) ++answer;

        ll difference = b - a;
        ll operations = difference / k;

        if (operations > 5) operations -= 3;

        answer += operations * 2;
        b -= operations * k;
    }

    answer += solve(a, b, k);
    cout << answer << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll k;
const ll inf = 1LL << 30;
unordered_map<ll, ll> memo;

ll solve(ll a, ll b) {
    if (b < a) return inf;
    if (a == b) return 0;

    auto it = memo.find(b);
    if (it != memo.end()) return it->second;

    ll ret = solve(a, b - 1) + 1;
    for (ll i = 2; i <= k; ++i) {
        if (b % i != 0) {
            ret = min(ret, solve(a, b - b % i) + 1);
        }
    }

    return memo[b] = ret;
}

