#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll k;

ll solve(ll a, ll b) {
    if (b < a) return (1LL << 60);
    if (a == b) return 0;

    size_t n = static_cast<size_t>(b - a + 1);
    vector<ll> maxDivisor(n, 0);

    ll limit = min(k, b);
    for (ll i = 2; i <= limit; ++i) {
        ll remainder = a % i;
        ll first = remainder == 0 ? a : a + (i - remainder);

        for (ll value = first; value <= b;) {
            maxDivisor[static_cast<size_t>(value - a)] = i;
            if (value > b - i) break;
            value += i;
        }
    }

    if (a == 0) maxDivisor[0] = k;

    using State = pair<ll, size_t>;
    priority_queue<State, vector<State>, greater<State>> active;

    ll answer = 0;

    for (size_t index = 0; index < n; ++index) {
        if (index > 0) {
            while (!active.empty() && active.top().second < index)
                active.pop();
            answer = active.top().first;
        }

        ll reach = max(1LL, maxDivisor[index] - 1);
        size_t endpoint = static_cast<size_t>(
            min<ll>(static_cast<ll>(n - 1), static_cast<ll>(index) + reach)
        );

        if (endpoint > index)
            active.emplace(answer + 1, endpoint);
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, ans = 0;
    cin >> b >> a >> k;

    ll v1 = b % k;
    if (b - v1 >= a) {
        b -= v1;
        ans++;

        ll diff = b - a;
        ll op = diff / k;
        if (op > 5) op -= 3;

        ans += op * 2;
        b -= op * k;
    }

    ans += solve(a, b);
    cout << ans << '\n';
}

